using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Reflection;using UnityEditor;using UnityEditorInternal;using UnityEngine;
namespace IdleIntelligence.Editor {
 public static class AnalyzeCapture {
  public static void Run(){string input=Environment.GetEnvironmentVariable("IDLE_RAW_PROFILE"),output=Environment.GetEnvironmentVariable("IDLE_RAW_SUMMARY");if(string.IsNullOrEmpty(input)||string.IsNullOrEmpty(output))throw new InvalidOperationException("Explicit input/output required");var method=typeof(ProfilerDriver).GetMethods(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static).First(m=>m.Name=="LoadProfile"&&m.GetParameters().Length==2);var result=method.Invoke(null,new object[]{input,false});if(result is bool valid&&!valid)throw new InvalidOperationException("Profiler rejected capture");var names=new Dictionary<int,string>();var times=new Dictionary<string,double>();var calls=new Dictionary<string,long>();int frames=0;var lines=new List<string>{"frame,layoutCalls,layoutMs,canvasBuildCalls,canvasBuildMs,gcCalls,gcBytes"};for(int f=ProfilerDriver.firstFrameIndex;f<=ProfilerDriver.lastFrameIndex;f++){using(var data=ProfilerDriver.GetRawFrameDataView(f,0)){if(!data.valid)continue;frames++;int layouts=0,batches=0,gcs=0;long bytes=0;double layout=0,batch=0;for(int i=0;i<data.sampleCount;i++){int id=data.GetSampleMarkerId(i);if(!names.TryGetValue(id,out string name))names[id]=name=data.GetMarkerName(id);if(string.IsNullOrEmpty(name))continue;if(name=="Layout"){layouts++;layout+=data.GetSampleTimeMs(i);}if(name=="Canvas.BuildBatch"){batches++;batch+=data.GetSampleTimeMs(i);}if(name=="GC.Alloc"){gcs++;bytes+=data.GetSampleMetadataAsLong(i,0);}if(name.StartsWith("Idle.",StringComparison.Ordinal)||name.Contains("Layout")||name.StartsWith("Canvas.",StringComparison.Ordinal)){times.TryGetValue(name,out double sum);times[name]=sum+data.GetSampleTimeMs(i);calls.TryGetValue(name,out long count);calls[name]=count+1;}}lines.Add(string.Join(",",f,layouts,layout.ToString("R",CultureInfo.InvariantCulture),batches,batch.ToString("R",CultureInfo.InvariantCulture),gcs,bytes));}}Directory.CreateDirectory(output);File.WriteAllLines(Path.Combine(output,"raw-frames.csv"),lines);File.WriteAllLines(Path.Combine(output,"raw-markers.tsv"),new[]{"frames="+frames,"marker\tcalls\ttotalInclusiveMs\tmeanInclusiveMsPerFrame"}.Concat(times.OrderByDescending(p=>p.Value).Select(p=>p.Key+"\t"+calls[p.Key]+"\t"+p.Value.ToString("F6",CultureInfo.InvariantCulture)+"\t"+(p.Value/Math.Max(1,frames)).ToString("F6",CultureInfo.InvariantCulture))));Debug.Log("RAW_PROFILE_ANALYZED frames="+frames+" output="+output);if(frames==0)throw new InvalidOperationException("No native frames decoded");}
 }
}
